module video_npu_top_77b8d5bfaa14 #(
        parameter DW_AVB_ADDR = 32,
        parameter DW_AVB_DATA = 64,
        parameter DW_AVB_STB  = 8,
        parameter DW_AVB_LEN  = 8,
        parameter DW_AVB_ID   = 4,
        parameter AXIS_ADDR_WD   = 6'd33,
        parameter AXIS_DT_WD     = 6'd32,
        parameter AXIS_DT_NB     = 4'd4,
        parameter AXIS_BURSTP_WD = 4'd4,
        parameter AXIS_ID_WD     = 4'd12,
        parameter AXIM_ADDR_WD   = 6'd33,
        parameter AXIM_DT_WD     = 7'd64,
        parameter AXIM_DT_NB     = 4'd8,
        parameter AXIM_BURSTP_WD = 4'd4,
        parameter AXIM_ID_WD     = 4'd6
)
(
        input   wire   M_AXI_ACLK,
        input   wire   M_AXI_AResetn,
        input   wire   S_AXILite_ACLK,
        input   wire   S_AXILite_AResetn,

        //---AXI4-Lite,Configure registers;
        //AW channel
        input   wire   [AXIS_ADDR_WD -1:0]      s_axilite_awaddr_i,
        input   wire   [2:0]                    s_axilite_awprot_i,
        input   wire                            s_axilite_awvalid_i,
        output  wire                            s_axilite_awready_o,
        //W channel
        input   wire   [AXIS_DT_WD -1:0]        s_axilite_wdata_i,
        input   wire   [AXIS_DT_NB -1:0]        s_axilite_wstrb_i,
        input   wire                            s_axilite_wvalid_i,
        output  wire                            s_axilite_wready_o,
        //B channel
        output  wire                            s_axilite_bvalid_o,
        output  wire   [1:0]                    s_axilite_bresp_o,
        input   wire                            s_axilite_bready_i,
        //AR channel
        input   wire   [AXIS_ADDR_WD -1:0]      s_axilite_araddr_i,
        input   wire   [2:0]                    s_axilite_arprot_i,
        input   wire                            s_axilite_arvalid_i,
        output  wire                            s_axilite_arready_o,
        //R channel
        output  wire   [AXIS_DT_WD -1:0]        s_axilite_rdata_o,
        output  wire   [1:0]                    s_axilite_rresp_o,
        output  wire                            s_axilite_rvalid_o,
        input   wire                            s_axilite_rready_i,

        //---AXI4,Read and write DDR;
        //AW channel
        input   wire                            m_axi_awready_soft_i,
        output  wire   [AXIM_ID_WD -1:0]        m_axi_awid_soft_o,
        output  wire   [AXIM_ADDR_WD -1:0]      m_axi_awaddr_soft_o,
        output  wire   [AXIM_BURSTP_WD -1:0]    m_axi_awlen_soft_o,
        output  wire   [1:0]                    m_axi_awsize_soft_o,
        output  wire   [1:0]                    m_axi_awburst_soft_o,
        output  wire   [2:0]                    m_axi_awprot_soft_o,
        output  wire                            m_axi_awvalid_soft_o,
        output  wire                            m_axi_awlock_soft_o,
        output  wire   [3:0]                    m_axi_awcache_soft_o,
        //W channel
        output  wire   [AXIM_DT_WD -1:0]        m_axi_wdata_soft_o,
        output  wire   [AXIM_DT_NB -1:0]        m_axi_wstrb_soft_o,
        input   wire                            m_axi_wready_soft_i,
        output  wire                            m_axi_wlast_soft_o,
        output  wire                            m_axi_wvalid_soft_o,
        //B channel
        input   wire   [AXIM_ID_WD -1:0]        m_axi_bid_soft_i,
        input   wire   [1:0]                    m_axi_bresp_soft_i,
        input   wire                            m_axi_bvalid_soft_i,
        output  wire                            m_axi_bready_soft_o,
        //AR channel
        input   wire                            m_axi_arready_soft_i,
        output  wire   [AXIM_ID_WD -1:0]        m_axi_arid_soft_o,
        output  wire   [AXIM_ADDR_WD -1:0]      m_axi_araddr_soft_o,
        output  wire   [AXIM_BURSTP_WD -1:0]    m_axi_arlen_soft_o,
        output  wire   [1:0]                    m_axi_arsize_soft_o,
        output  wire   [1:0]                    m_axi_arburst_soft_o,
        output  wire   [2:0]                    m_axi_arprot_soft_o,
        output  wire                            m_axi_arvalid_soft_o,
        output  wire                            m_axi_arlock_soft_o,
        output  wire   [3:0]                    m_axi_arcache_soft_o,
        //R channel
        input   wire   [AXIM_ID_WD -1:0]        m_axi_rid_soft_i,
        input   wire   [AXIM_DT_WD -1:0]        m_axi_rdata_soft_i,
        input   wire   [1:0]                    m_axi_rresp_soft_i,
        input   wire                            m_axi_rlast_soft_i,
        input   wire                            m_axi_rvalid_soft_i,
        output  wire                            m_axi_rready_soft_o,

        `ifdef SOFT_HDMI_DISPLAY_77b8d5bfaa14
        // HDMI interface
        output  wire                            hdmi_out_clk,
        output  wire                            hdmi_16_hsync,
        output  wire                            hdmi_16_vsync,
        output  wire                            hdmi_16_data_e,
        output  wire   [15:0]                   hdmi_16_data,
        `endif

        //---video npu interrupt
        output  wire   npu_soft_intr

);
